import { readFile } from "node:fs/promises";
import { runChecked, type CommandRunner } from "../../process.js";

export async function baseExists(runner: CommandRunner, root: string, base: string): Promise<boolean> {
  const fetched = await runner.run(["git", "fetch", "--depth=1", "origin", base], { cwd: root });
  if (fetched.exitCode !== 0) return false;
  return (await runChecked(runner, ["git", "cat-file", "-t", base], { cwd: root })).trim() === "commit";
}

